import pygame

def make_paddle(width, height, side):
    if side != "left" and side != "right":
        raise ValueError("Unknown side")
    paddle = pygame.Rect(0, 0, 12, 72)
    paddle.centery = height // 2
    if side == "left":
        paddle.left = 24
    else:
        paddle.right = width - 24
    return paddle
